/**
 * Whether `name` is part of the icon set. Lets callers accept an icon name
 * contributed from outside (e.g. a plugin naming its tab icon) and fall back
 * to their own default when it is unknown.
 */
export function isIconName(name: string): name is IconName {
  return Object.prototype.hasOwnProperty.call(iconRegistry, name)
}

export interface IconProps {
  name: IconName
  /** Override the default size (px) */
  size?: number | string
  /** Override the default stroke width */
  strokeWidth?: number
  /** Override the fill (solid) */
  filled?: boolean
  className?: string
  style?: React.CSSProperties
}

export function Icon({
  name,
  size,
  strokeWidth,
  filled,
  className,
  style,
}: IconProps) {
  const def = iconRegistry[name]
  if (!def) return null

  const isFilled = filled ?? def.filled ?? false
  const sw = strokeWidth ?? def.strokeWidth

  // Solid icons: no stroke, or stroke same color as fill (keep original look with currentColor fill)
  const fill = isFilled ? 'currentColor' : 'none'
  const stroke = isFilled && sw === 0 ? 'none' : 'currentColor'

  return (
    <svg
      className={className}
      style={style}
      width={size ?? def.size}
      height={size ?? def.size}
      viewBox={v}
      fill={fill}
      stroke={stroke}
      strokeWidth={sw}
      strokeLinecap="round"
      strokeLinejoin="round"
      xmlns="http://www.w3.org/2000/svg"
    >
      {def.node}
    </svg>
  )
}

export default Icon
